'use strict';
const DATA=window.LINKRADAR_DATA, $=id=>document.getElementById(id), fmt=(x,d=3)=>Number(x).toLocaleString('zh-CN',{maximumFractionDigits:d}), precise=x=>Number(x).toFixed(6), ns='http://www.w3.org/2000/svg';
let current='facebook', selected=null, page=0, networkTransform={x:0,y:0,k:1};
const d=()=>DATA.datasets[current];
function svgNode(tag,attrs={},text=null){const el=document.createElementNS(ns,tag);for(const[k,v]of Object.entries(attrs))el.setAttribute(k,v);if(text!==null)el.textContent=text;return el}
function metric(label,value,note){return `<div class="metric"><span>${label}</span><strong>${value}</strong><small>${note}</small></div>`}
function selectNode(index){selected=d().nodes.find(n=>n.index===index);renderDetails();renderBars();renderTable();paintSelection()}
function renderDetails(){const n=selected||d().top10[0];$('selectedBadge').textContent=`介数第 ${n.rank_bc} 名`;$('node-detail').innerHTML=`<div class="node-id">${n.original_id}<small>匿名原始 ID</small></div><div class="details"><div><span>归一化介数</span><strong>${precise(n.bc_normalized)}</strong></div><div><span>raw 介数</span><strong>${fmt(n.bc_raw,2)}</strong></div><div><span>度数 / 度排名</span><strong>${n.degree} / #${n.rank_degree}</strong></div><div><span>所在分量 / 是否割点</span><strong>${fmt(n.component_size)} / ${n.is_articulation?'是':'否'}</strong></div></div>`;
$('node-insight').textContent=n.is_articulation?'这个节点是完整原图的割点：单独删除它会增加连通分量数量。高介数与割点性质分别计算，含义不同。':`这个节点不是原图割点。它的介数排名为第 ${n.rank_bc}、度排名为第 ${n.rank_degree}；承担中转作用不要求拥有最多的直接连接。`}
function renderBars(){const nodes=d().top10,max=Math.max(...nodes.map(n=>n.bc_normalized),1e-30);$('bar-chart').replaceChildren();for(const n of nodes){const b=document.createElement('button');b.className='bar-row'+(selected?.index===n.index?' selected':'');b.setAttribute('aria-label',`检查节点 ${n.original_id}，介数排名 ${n.rank_bc}`);b.innerHTML=`<span>${n.original_id}</span><span class="track"><span class="bar" style="width:${n.bc_normalized/max*100}%"></span></span><span class="bar-val">${precise(n.bc_normalized)}</span>`;b.onclick=()=>selectNode(n.index);$('bar-chart').append(b)}}
function filteredRows(){const query=$('search').value.trim(),mode=$('sort').value;let rows=[...d().nodes].sort((a,b)=>mode==='bc'?a.rank_bc-b.rank_bc:a.rank_degree-b.rank_degree);if(query)rows=rows.filter(n=>String(n.original_id).includes(query));else if($('range').value==='top')rows=rows.slice(0,10);return rows}
function renderTable(){const rows=filteredRows(),pages=Math.max(1,Math.ceil(rows.length/10));page=Math.min(page,pages-1);$('node-table').replaceChildren();for(const n of rows.slice(page*10,page*10+10)){const tr=document.createElement('tr');tr.className='node-row'+(selected?.index===n.index?' selected':'');tr.tabIndex=0;tr.setAttribute('aria-label',`选择节点 ${n.original_id}`);tr.innerHTML=`<td>${$('sort').value==='bc'?n.rank_bc:n.rank_degree}</td><td class="id">${n.original_id}</td><td>${n.degree}</td><td>${n.rank_degree}</td><td>${fmt(n.bc_raw,3)}</td><td>${n.bc_normalized.toFixed(9)}</td><td>${fmt(n.component_size)}</td><td>${n.is_articulation?'是':'否'}</td>`;tr.onclick=()=>selectNode(n.index);tr.onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();selectNode(n.index)}};$('node-table').append(tr)}if(!rows.length){const tr=document.createElement('tr');tr.innerHTML='<td colspan="8">没有匹配的原始 ID。</td>';$('node-table').append(tr)}$('row-count').textContent=`${rows.length} 个匹配节点 / 全图 ${d().n}`;$('page-state').textContent=`${page+1} / ${pages}`;$('previous').disabled=page===0;$('next').disabled=page+1>=pages}
function paintSelection(){document.querySelectorAll('.node-circle').forEach(el=>{const hit=Number(el.dataset.index)===selected?.index;el.setAttribute('stroke',hit?'#244e41':'#fff');el.setAttribute('stroke-width',hit?'3':'1.2')});document.querySelectorAll('.network-edge').forEach(el=>{const hit=Number(el.dataset.u)===selected?.index||Number(el.dataset.v)===selected?.index;el.setAttribute('stroke',hit?'#276e5d':'#92ada1');el.setAttribute('opacity',hit?'.7':'.15')})}
function renderNetwork(){const graph=d().subgraph, svg=svgNode('svg',{viewBox:'0 0 800 480',role:'img','aria-label':`${d().title} 介数前十附近的${graph.nodes.length}节点局部图`}),g=svgNode('g');networkTransform={x:0,y:0,k:1};svg.append(g);const lookup=new Map(graph.nodes.map(n=>[n.index,n])),xy=n=>[70+(n.x+1)*330,40+(n.y+1)*195];for(const[u,v]of graph.edges){const a=xy(lookup.get(u)),b=xy(lookup.get(v));const edge=svgNode('line',{x1:a[0],y1:a[1],x2:b[0],y2:b[1],stroke:'#92ada1','stroke-width':.7,opacity:.15,class:'network-edge'});edge.dataset.u=u;edge.dataset.v=v;g.append(edge)}for(const n of graph.nodes){const[x,y]=xy(n),r=n.top10?5+13*Math.sqrt(n.bc_normalized/d().top10[0].bc_normalized):3.2;const circle=svgNode('circle',{cx:x,cy:y,r,fill:n.top10?'#cc824a':'#8bb8a9',class:'node-circle',tabindex:'0','aria-label':`节点 ${n.original_id}，全图介数排名 ${n.rank_bc}`});circle.dataset.index=n.index;circle.append(svgNode('title',{},`ID ${n.original_id} | BC ${precise(n.bc_normalized)} | degree ${n.degree}`));circle.onclick=()=>selectNode(n.index);circle.onkeydown=e=>{if(e.key==='Enter')selectNode(n.index)};g.append(circle);if(n.top10)g.append(svgNode('text',{x:x+r+3,y:y+3,class:'node-label'},String(n.original_id)))}const update=()=>g.setAttribute('transform',`translate(${networkTransform.x} ${networkTransform.y}) scale(${networkTransform.k})`);let drag=null;svg.addEventListener('pointerdown',e=>{if(e.target.classList.contains('node-circle'))return;drag={x:e.clientX,y:e.clientY,tx:networkTransform.x,ty:networkTransform.y};svg.setPointerCapture(e.pointerId)});svg.addEventListener('pointermove',e=>{if(!drag)return;const box=svg.getBoundingClientRect();networkTransform.x=drag.tx+(e.clientX-drag.x)*800/box.width;networkTransform.y=drag.ty+(e.clientY-drag.y)*480/box.height;update()});svg.addEventListener('pointerup',()=>drag=null);svg.addEventListener('wheel',e=>{e.preventDefault();networkTransform.k=Math.max(.4,Math.min(4,networkTransform.k*(e.deltaY<0?1.12:.9)));update()},{passive:false});$('network').replaceChildren(svg);$('reset-network').onclick=()=>{networkTransform={x:0,y:0,k:1};update()};$('subgraph-note').textContent=`本视图 ${graph.nodes.length} 个节点、${graph.edges.length} 条边。${graph.note} 全图仍为 ${fmt(d().n)} 节点、${fmt(d().m)} 条边。`;paintSelection()}
function renderRobust(){const rows=d().robustness,svg=svgNode('svg',{viewBox:'0 0 900 400',role:'img','aria-label':'固定排名节点移除与最大连通分量占比'}),x=q=>65+q/.2*790,y=v=>340-v*300;for(let v=0;v<=1.001;v+=.2){svg.append(svgNode('line',{x1:65,y1:y(v),x2:855,y2:y(v),stroke:'#e2e8e0'}),svgNode('text',{x:50,y:y(v)+4,'text-anchor':'end',fill:'#6b7d70','font-size':11},v.toFixed(1)))}for(const q of [0,.05,.1,.15,.2])svg.append(svgNode('text',{x:x(q),y:363,'text-anchor':'middle',fill:'#6b7d70','font-size':11},`${Math.round(q*100)}%`));const colors={bc:'#197b6e',degree:'#c57d44',random:'#6b88a5'},labels={bc:'介数固定排名',degree:'度数固定排名',random:'随机均值（20次）'};for(const[strategy,color]of Object.entries(colors)){const pts=rows.filter(r=>r.strategy===strategy).sort((a,b)=>a.k-b.k);if(strategy==='random'){const points=[...pts.map(r=>[x(r.removed_fraction),y(r.lcc_original_p10)]),...pts.slice().reverse().map(r=>[x(r.removed_fraction),y(r.lcc_original_p90)])];svg.append(svgNode('polygon',{points:points.map(p=>p.join(',')).join(' '),fill:color,opacity:.17}))}svg.append(svgNode('polyline',{points:pts.map(r=>`${x(r.removed_fraction)},${y(r.lcc_original_mean)}`).join(' '),fill:'none',stroke:color,'stroke-width':2.7}));for(const r of pts){const dot=svgNode('circle',{cx:x(r.removed_fraction),cy:y(r.lcc_original_mean),r:4,fill:color});dot.append(svgNode('title',{},`${labels[strategy]} | k=${r.k} | LCC/n=${Number(r.lcc_original_mean).toFixed(6)}`));svg.append(dot)}const j=Object.keys(colors).indexOf(strategy);svg.append(svgNode('line',{x1:85+j*245,y1:18,x2:107+j*245,y2:18,stroke:color,'stroke-width':3}),svgNode('text',{x:115+j*245,y:22,fill:'#496152','font-size':11},labels[strategy]))}svg.append(svgNode('text',{x:460,y:393,'text-anchor':'middle','font-size':11,fill:'#718276'},'移除节点 / 原始节点数'));$('robust-chart').replaceChildren(svg);const maxk=Math.max(...rows.map(r=>r.k)),last=Object.fromEntries(rows.filter(r=>r.k===maxk).map(r=>[r.strategy,r]));$('robust-note').textContent=`初始 LCC/n=${(d().lcc_size/d().n).toFixed(4)}。移除 ${maxk} 个节点（${(last.bc.removed_fraction*100).toFixed(3)}%）后，介数=${last.bc.lcc_original_mean.toFixed(6)}，度数=${last.degree.lcc_original_mean.toFixed(6)}，随机均值=${last.random.lcc_original_mean.toFixed(6)}。${last.bc.lcc_original_mean<last.degree.lcc_original_mean?'此末点介数策略造成的最大分量更小。':'此末点度数策略造成的最大分量更小或相同。'} 这不是所有比例或网络上的普遍结论。`}
function renderMethod(){
const candidate=DATA.paired_by_dataset?.[current]??DATA.paired;
const paired=candidate?.manifest?.dataset_id===current?candidate:null;
$('paired-title').textContent=`${d().title} 相邻区组复测`;
if(!paired||!paired.summary?.length){
  $('paired-status').innerHTML=`<div class="insight warning">${d().title}尚未导入可展示的配对复测结果。下方保留该网络首轮实测，不使用其他网络的数据替代。</div>`;
}else{
  const ok=paired.manifest.baseline_comparability_screen_passed;
  const chart=`assets/${current}_paired.png`;
  let html=`<div class="insight ${ok?'':'warning'}">状态：${paired.manifest.status}；固定逻辑CPU亲和性：${paired.manifest.logical_cpu_affinity.join(', ')}。单工作进程可比性启发式筛查：${ok?'通过':'未通过'}。此筛查不是统计显著性检验；不同网络和协议的记录分别统计。${ok?'':'筛查未通过，本轮四进程比值仅作描述，不作可靠多核加速结论。'}</div><div class="paired-grid"><div class="table-scroll"><table><thead><tr><th>模式</th><th>p</th><th>次数</th><th>total / s</th><th>观察比值</th></tr></thead><tbody>`;
  for(const r of paired.summary)html+=`<tr><td>${r.mode}</td><td>${r.p_used}</td><td>${r.count}</td><td>${Number(r.median_total).toFixed(3)}</td><td>${Number(r.observed_speedup_total).toFixed(3)}</td></tr>`;
  html+=`</tbody></table></div><a class="paired-chart-link" href="${chart}" target="_blank" rel="noopener" aria-label="查看${d().title}配对复测完整图"><img class="figure" src="${chart}" alt="${d().title}固定逻辑CPU亲和性区组复测"></a></div><p class="caption">一次全图串行热身不进入统计；三个相邻区组，每种条件在每个顺序位置各出现一次。柱为中位数，散点为各次实测，误差线为min–max。p=1区组比值在[0.8,1.25]只是预先声明的诊断范围；CPU频率和后台负载未锁定。点击图片可查看完整分辨率。</p>`;
  $('paired-status').innerHTML=html;
}
$('performance-note').className='insight'+(current==='facebook'?' warning':'');$('performance-note').textContent=current==='facebook'?'首轮 Facebook 单工作进程也出现约2倍的观察比值，提示运行条件不一致。本表仅保留历史实测，不将四进程比值解释为可靠多核收益；新配对复测在上方单列。':'ca-GrQc为首轮三次重复，total包含启动；p=1约1.06，四进程约2.61。仍需考虑重复波动，不能直接推广到其他机器。';$('performance-table').replaceChildren();for(const r of [...d().timings].sort((a,b)=>a.mode.localeCompare(b.mode)||a.p_used-b.p_used)){const tr=document.createElement('tr');tr.innerHTML=`<td>${r.mode}</td><td>${r.p_used}</td><td>${r.count}</td><td>${Number(r.median_total).toFixed(3)}</td><td>${Number(r.median_steady).toFixed(3)}</td><td>${Number(r.speedup_total).toFixed(3)}</td>`;$('performance-table').append(tr)}$('provenance').textContent=`来源结果：${DATA.reference_run} ｜ 图SHA256：${d().graph_sha256} ｜ 原文件SHA256：${d().raw_sha256} ｜ 全节点NetworkX raw最大误差：${d().validation.raw.max_abs_error} ｜ 原始自环行数：${d().self_loop_rows} ｜ 去重行数：${d().duplicate_edge_rows}`}
function render(){page=0;selected=d().top10[0];$('metrics').innerHTML=metric('原始节点数',fmt(d().n),'保留全部已知孤立点')+metric('唯一无向边',fmt(d().m),`平均度 ${d().average_degree.toFixed(3)}`)+metric('连通分量',fmt(d().components),'完整原图，不只取最大分量')+metric('初始 LCC / n',`${(d().lcc_size/d().n*100).toFixed(2)}%`,`最大分量 ${fmt(d().lcc_size)} 节点`);$('downloadTop').href=`assets/${current}_top10.csv`;$('downloadAll').href=`assets/${current}_all_nodes.csv`;$('scatter-image').src=`assets/${current}_degree_bc.png`;renderBars();renderDetails();renderTable();renderNetwork();renderRobust();renderMethod()}
$('dataset').onchange=e=>{current=e.target.value;$('search').value='';render()};for(const id of ['search','sort','range'])$(id).addEventListener(id==='search'?'input':'change',()=>{page=0;renderTable()});$('previous').onclick=()=>{page--;renderTable()};$('next').onclick=()=>{page++;renderTable()};function viewFromHash(){const anchor=location.hash.slice(1);return anchor==='theory'||anchor.startsWith('theory-')?'theory':['nodes','robust','method'].includes(anchor)?anchor:'nodes'}
function showView(view,scroll=true){document.querySelectorAll('.nav').forEach(button=>{const active=button.dataset.tab===view;button.classList.toggle('active',active);if(active)button.setAttribute('aria-current','page');else button.removeAttribute('aria-current')});document.querySelectorAll('.view').forEach(el=>el.classList.toggle('active',el.id===view));if(scroll)window.scrollTo({top:0,behavior:'smooth'})}
document.querySelectorAll('.nav').forEach(button=>button.onclick=()=>{showView(button.dataset.tab);history.replaceState(null,'','#'+button.dataset.tab)});
window.addEventListener('hashchange',()=>{showView(viewFromHash(),false);const target=document.getElementById(location.hash.slice(1));if(target)target.scrollIntoView()});showView(viewFromHash(),false);render();
